var logElement;
const init = (el) => {
  logElement = el;
};
const log2 = (msg, className = "") => {
  console.log("logging", msg, className);
  if (logElement)
    logElement.innerHTML = ` >> <span class=${className}> ${msg} </span> `;
};
const hide = () => {
  if (logElement)
    logElement.style.display = "none";
};
const show = () => {
  if (logElement)
    logElement.style.display = "block";
};
const toggle = () => {
  if (logElement.style.display == "none") {
    logElement.style.display = "block";
  } else {
    logElement.style.display = "none";
  }
};
const exports = { init, log: log2, hide, show, toggle };
const repl = {
  eval: (arg, callback) => {
    var jsString = `(async() => {
    ${arg}
})().catch(${(err) => log2(err.message, "log-error")})`;
    var isError2 = false;
    try {
      window.eval(jsString);
      log2("");
    } catch (e) {
      isError2 = true;
      console.log("logging", e);
      log2(e.message, "log-error");
    }
    if (callback)
      callback(jsString, isError2);
  }
};
